(621299, 63906, 14837, '<td valign="top">A bit dark for me, but I love that look!</td>', 'A bit dark for me, but I love that look!', '2004-03-15 02:32:49.000000', NULL, 1),
(621300, 64370, 14837, '<td valign="top">Nice colors, focusing and such a cutie!</td>', 'Nice colors, focusing and such a cutie!', '2004-03-15 02:33:09.000000', NULL, 1),
(621301, 64566, 14837, '<td valign="top">LoL!!  That look is priceless!</td>', 'LoL!!  That look is priceless!', '2004-03-15 02:33:36.000000', NULL, 1),
