(623667, 64166, 14837, '<td valign="top">Very cute..... a bit blurry, but nice shot</td>', 'Very cute..... a bit blurry, but nice shot', '2004-03-16 14:37:04.000000', NULL, 1),
(623668, 64327, 14837, '<td valign="top">I like how you went for something different.  Very modern.  Great shot</td>', 'I like how you went for something different.  Very modern.  Great shot', '2004-03-16 14:37:33.000000', NULL, 1),
(623670, 64592, 14837, '<td valign="top">Beautiful girl!  The shot is nice, but the lighting on her face is a bit harsh.  Nice DOF</td>', 'Beautiful girl!  The shot is nice, but the lighting on her face is a bit harsh.  Nice DOF', '2004-03-16 14:38:18.000000', NULL, 1),
