(625683, 64557, 6019, '<td valign="top">excellent pic</td>', 'excellent pic', '2004-03-17 14:06:30.000000', NULL, 1),
(625686, 64036, 6019, '<td valign="top">for me, just too bright, try it in monotone! Good pose and use of hand...</td>', 'for me, just too bright, try it in monotone! Good pose and use of hand...', '2004-03-17 14:07:23.000000', NULL, 1),
