(630447, 64280, 1368, '<td valign="top">Beautiful portrait, I love a face that tells a story and this one sure does, great lightning, colors and dof too, Good luck :)</td>', 'Beautiful portrait, I love a face that tells a story and this one sure does, great lightning, colors and dof too, Good luck :)', '2004-03-21 18:58:41.000000', NULL, 1),
(630448, 64653, 1368, '<td valign="top">Beautiful picture of a beautiful girl I like the position of it in the frame and the lightning good luck :)</td>', 'Beautiful picture of a beautiful girl I like the position of it in the frame and the lightning good luck :)', '2004-03-21 18:59:54.000000', NULL, 1),
(630449, 64204, 1368, '<td valign="top">Very cool point of view I like the stairs in the front and the shoes Good job :)</td>', 'Very cool point of view I like the stairs in the front and the shoes Good job :)', '2004-03-21 19:01:33.000000', NULL, 1),
(630450, 64451, 11800, '<td valign="top">This is a good industrial portrait. Suitable for a cd or press release. The lighting is perfect. Very good job. The palette is even harmonious.</td>', 'This is a good industrial portrait. Suitable for a cd or press release. The lighting is perfect. Very good job. The palette is even harmonious.', '2004-03-21 19:01:39.000000', NULL, 1),
(630451, 64500, 1368, '<td valign="top">Beautiful lightning and tones Great picture!</td>', 'Beautiful lightning and tones Great picture!', '2004-03-21 19:02:12.000000', NULL, 1),
