(630485, 64589, 11769, '<td valign="top">Wonderful capture. Just love the feeling here. Great work!</td>', 'Wonderful capture. Just love the feeling here. Great work!', '2004-03-21 19:19:27.000000', NULL, 1),
(630486, 64505, 1368, '<td valign="top">The look on his face is so adorable! I like the positioning good luck - 8</td>', 'The look on his face is so adorable! I like the positioning good luck - 8', '2004-03-21 19:19:27.000000', NULL, 1),
